// 1. Recupera o texto de forma segura
let inputText = $json["output"] || $json["outputText"] || "";

// 2. Remove TODOS os colchetes [ ] que a IA insere
let formattedText = inputText.replace(/[\[\]]/g, '');

// 3. Converte negritos de **exemplo** para *exemplo* (WhatsApp)
formattedText = formattedText.replace(/\*\*(.*?)\*\*/g, '*$1*');

// 4. CORREÇÃO DAS QUEBRAS DE LINHA:
// Substitui a sequência de texto "\n" por quebras de linha reais do sistema
formattedText = formattedText.replace(/\\n/g, '\n');

// 5. Garante que não existam quebras triplas e limpa espaços nas bordas
formattedText = formattedText.replace(/\n{3,}/g, '\n\n').trim();

// 6. Captura os dados externos para montar o bloco final
const nomeGrupo = $('Webhook').first().json.body.nome_do_grupo || "Grupo";
const totalMsg = $('Pegar total de palavras').first().json.totalMensagens || 0;

// Montagem final com as variáveis externas inseridas diretamente no texto
const mensagemFinal = `*RESUMO DO GRUPO: ${nomeGrupo}*

${formattedText}

*Estatísticas gerais:*
Total de mensagens hoje: ${totalMsg}`;

return {
  json: {
    outputText: mensagemFinal
  }
};

