// 1. Pega a data de hoje no formato YYYY-MM-DD
const hoje = new Date().toISOString().split('T')[0];

return items.filter(item => {
  const msg = item.json;

  // Converte o timestamp da mensagem (segundos) para YYYY-MM-DD
  // Multiplicamos por 1000 porque o JS usa milissegundos
  const dataMensagem = new Date(msg.created_at * 1000).toISOString().split('T')[0];

  // 1. Filtra apenas mensagens de humanos
  const eMensagemHumana = msg.message_type === 0;

  // 2. Compara se a data é exatamente a mesma de hoje (ignora horas)
  const eMesmoDia = dataMensagem === hoje;

  // 3. Garante que tenha conteúdo de texto
  const temConteudo = msg.content && msg.content.trim() !== "";

  return eMensagemHumana && eMesmoDia && temConteudo;
});

const inicioDoDiaUnix = Math.floor(new Date().setHours(0, 0, 0, 0) / 1000);

return items.map(item => {
  const msg = item.json;
  let nomeExtraido = "Desconhecido";
  let textoExtraido = msg.content || "";
  let tipoFinal = "outros";
  let urlConteudo = "";

  // 1. Identificação do Tipo (Incluindo 'file') e Extração de URL
  if (msg.attachments && msg.attachments.length > 0) {
    const anexo = msg.attachments[0];
    urlConteudo = anexo.data_url || "";

    if (anexo.file_type === "image") {
      tipoFinal = "image";
    } else if (anexo.file_type === "audio") {
      tipoFinal = "audio";
    } else if (anexo.file_type === "file" || anexo.file_type === "plain") { 
      // Captura documentos/arquivos em geral
      tipoFinal = "file";
    } else {
      tipoFinal = "outros";
    }
  } else if (msg.content_type === "text" && textoExtraido !== "") {
    tipoFinal = "text";
  }

  // 2. Separação de Nome e Mensagem
  if (textoExtraido.includes(':**\n')) {
    const partes = textoExtraido.split(':**\n');
    nomeExtraido = partes[0].replace(/\*\*/g, '').trim();
    textoExtraido = partes[1].trim();
  } else if (textoExtraido.startsWith('**')) {
    nomeExtraido = textoExtraido.replace(/\*\*/g, '').replace(':', '').trim();
    textoExtraido = ""; 
  }

  // 3. Regra de Negócio: Se for imagem, áudio ou arquivo, o conteúdo recebe a URL
  if (["image", "audio", "file"].includes(tipoFinal) && urlConteudo !== "") {
    // Se houver texto (legenda), concatena. Se não, usa apenas a URL.
    textoExtraido = textoExtraido !== "" ? `${textoExtraido} (Link: ${urlConteudo})` : urlConteudo;
  }

  // 4. Formatação da Data
  const dataObjeto = new Date(msg.created_at * 1000);
  const dataFormatada = dataObjeto.toLocaleString('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });

  return {
    json: {
      id: msg.id,
      nome_usuario: nomeExtraido,
      mensagem_texto: textoExtraido,
      tipo_mensagem: tipoFinal,
      data_envio: dataFormatada,
      url_original: urlConteudo
    }
  };
});

// Contagem do total de mensagens processadas
let totalMensagens = items.length;

return [
  {
    json: {
      totalMensagens
    }
  }
];

let todasMensagens = [];

// 1. Extrair e achatar todas as mensagens de todos os blocos de dados
for (const item of items) {
  if (item.json.data) {
    const mensagensNoBloco = JSON.parse(item.json.data);
    mensagensNoBloco.forEach(m => {
      todasMensagens.push({
        nome: m.Mensagem?.name_user || "Sistema",
        dataStr: m.Mensagem?.Data || "",
        // Converte a string "DD/MM/YYYY, HH:mm" para um objeto Date para ordenar
        timestamp: new Date(m.Mensagem?.Data.replace(/(\d{2})\/(\d{2})\/(\d{4})/, '$2/$1/$3')).getTime(),
        conteudo: m.mensagem_texto || m.text || m.content || ""
      });
    });
  }
}

// 2. Ordenar: Do menos atual (antigo) para o mais atual (recente)
todasMensagens.sort((a, b) => a.timestamp - b.timestamp);

// 3. Montar o texto formatado para o prompt da IA
let textoFinal = todasMensagens.map(m => `[${m.dataStr}] ${m.nome}: ${m.conteudo}`).join('\n\n');

return {
  texto_limpo_para_ia: textoFinal
};
